const LIFE_CYCLE = [['frog', ['egg', 'tadpole', 'froglet', 'adult frog']], ['butterfly', ['egg', 'caterpillar (larva)', 'chrysalis (pupa)', 'adult butterfly']], ['chicken', ['egg', 'chick', 'young chicken', 'adult chicken']], ['ladybug', ['egg', 'larva', 'pupa', 'adult ladybug']]];
const lifeCycleGen = () => {
  const [animal, st] = pick(LIFE_CYCLE), i = Math.floor(Math.random() * 3);
  return { type: 'mc', prompt: `In the life cycle of a ${animal}, what stage comes right after <strong>${st[i]}</strong>?`, answer: st[i + 1], choices: shuffle(st.filter(x => x !== st[i])), explain: `The ${animal} life cycle: ${st.join(' → ')}.` };
};
const constructCycle = () => {
  const [animal, st] = pick(LIFE_CYCLE), right = st.join(' → ');
  const wrong = [[st[1], st[0], st[2], st[3]], [st[0], st[2], st[1], st[3]], [st[3], st[0], st[1], st[2]]].map(x => x.join(' → '));
  return { type: 'mc', prompt: `Which shows the life cycle of a ${animal} in the correct order?`, answer: right, choices: shuffle([right, ...wrong]), explain: `The ${animal} life cycle: ${right}.` };
};
